"""
organise_by_index.py

Reads a mapping CSV (symbol, category) and creates symbolic links (or copies)
from the consolidated Parquet files into category‑specific folders.

Usage:
    python -m scripts.organise_by_index [--copy] [--dry-run]
"""

import shutil
import sys
from pathlib import Path

import polars as pl

# ---------- Configuration ----------
CONSOLIDATED_DIR = Path(r"C:\Exchange\data\consolidated_v2")
OUTPUT_BASE = Path(r"C:\Exchange\data\indices")
# Use the detailed mapping file generated by classify_symbols.py
MAPPING_FILE = Path(r"C:\Exchange\data\index_mapping_detailed.csv")


# ---------- Functions ----------

def load_mapping(mapping_path: Path) -> dict[str, str]:
    """Load symbol -> category mapping from CSV with columns 'symbol' and 'category'."""
    if not mapping_path.exists():
        print(f"Error: Mapping file not found: {mapping_path}")
        print("Please run classify_symbols.py first.")
        sys.exit(1)

    df = pl.read_csv(mapping_path)
    # Expect columns: symbol, category
    return dict(zip(df["symbol"], df["category"]))


def organise(mapping: dict[str, str], use_copy: bool = False, dry_run: bool = False):
    """Create category folders and link/copy symbol folders."""
    OUTPUT_BASE.mkdir(parents=True, exist_ok=True)

    symbol_folders = [d for d in CONSOLIDATED_DIR.iterdir() if d.is_dir()]
    print(f"Found {len(symbol_folders)} symbol folders.")

    for sym_dir in symbol_folders:
        symbol = sym_dir.name
        # If symbol not found, default to 'others' (should not happen with detailed mapping)
        category = mapping.get(symbol, "others")
        target_base = OUTPUT_BASE / category
        target_sym_dir = target_base / symbol

        if dry_run:
            print(f"Would process {symbol} -> {category}")
            continue

        target_base.mkdir(parents=True, exist_ok=True)

        if use_copy:
            if target_sym_dir.exists():
                print(f"Removing existing {target_sym_dir}")
                shutil.rmtree(target_sym_dir)
            shutil.copytree(sym_dir, target_sym_dir)
            print(f"Copied {symbol} to {target_sym_dir}")
        else:
            if target_sym_dir.exists():
                if target_sym_dir.is_symlink():
                    target_sym_dir.unlink()
                else:
                    print(f"Warning: {target_sym_dir} exists and is not a symlink. Skipping.")
                    continue
            try:
                target_sym_dir.symlink_to(sym_dir, target_is_directory=True)
                print(f"Created symlink {target_sym_dir} -> {sym_dir}")
            except OSError as e:
                print(f"Symlink failed for {symbol}, falling back to copy: {e}")
                shutil.copytree(sym_dir, target_sym_dir)
                print(f"Copied {symbol} to {target_sym_dir}")

    print("Done.")


def main():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--copy", action="store_true",
                        help="Copy files instead of using symlinks")
    parser.add_argument("--dry-run", action="store_true",
                        help="Show what would be done")
    args = parser.parse_args()

    mapping = load_mapping(MAPPING_FILE)
    organise(mapping, use_copy=args.copy, dry_run=args.dry_run)


if __name__ == "__main__":
    main()